-- ── 1. Sections ────────────────────────────────────────────────────────
INSERT INTO master_sections (slug, name, display_order)
VALUES
  ('externals', 'Site & Externals', 1),
  ('structure', 'Structure', 2),
  ('roofing', 'Roofing', 3),
  ('electrical', 'Electrical', 4),
  ('plumbing', 'Plumbing & Water', 5),
  ('hvac', 'HVAC & Mechanical', 6),
  ('life_safety', 'Life Safety', 7),
  ('interiors', 'Interiors', 8)
ON CONFLICT (slug) DO UPDATE
  SET name          = EXCLUDED.name,
      display_order = EXCLUDED.display_order;

