JOIN   master_conditions mc ON mc.slug = v.condition_slug
JOIN   inspection_types  it ON it.slug = v.inspection_slug
ON CONFLICT (inspection_type_id, condition_id) DO UPDATE
  SET is_required = EXCLUDED.is_required;

-- ── 4. Deactivate legacy conditions ────────────────────────────────────
-- Legacy slugs used descriptive names; they are superseded by this library.
UPDATE master_conditions
  SET is_active = FALSE
WHERE slug IN ('roof_covering', 'gutters_drainage', 'roof_structure', 'roof_flashings', 'external_walls', 'site_drainage', 'foundation_dampness', 'electrical_db', 'electrical_wiring', 'plumbing_supply', 'plumbing_waste', 'interior_finishes', 'damp_mould', 'structural_cracks', 'fire_safety', 'boundary_walls', 'roof_tiles', 'roof_gutters', 'drainage', 'dampness', 'cracks', 'electrical_sockets', 'electrical_lighting', 'plumbing_fixtures', 'structural_walls', 'structural_frame', 'hvac_cooling', 'hvac_ventilation', 'life_safety_fire', 'interior_walls', 'interior_floors', 'interior_ceilings');
